async function utworzPost(dane) {
  const odpowiedz = await fetch("https://jsonplaceholder.typicode.com/posts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(dane),
  });

  if (!odpowiedz.ok) throw new Error(`HTTP ${odpowiedz.status}`);
  return odpowiedz.json();
}

utworzPost({ tytul: "Test", userId: 1 }).then((wynik) => console.log(wynik.id));
// -> 101 (testowe API zawsze zwraca nowe id)

async function wyslijPlik(plik, opis) {
  const formData = new FormData();
  formData.append("plik", plik);
  formData.append("opis", opis);

  const odpowiedz = await fetch("/api/upload", {
    method: "POST",
    body: formData, // BEZ headers['Content-Type'] - fetch ustawia je sam
  });

  return odpowiedz.json();
}

async function wyslijZle(formData) {
  return fetch("/api/upload", {
    method: "POST",
    headers: { "Content-Type": "multipart/form-data" }, // ZLE - brak boundary!
    body: formData,
  });
}

async function wyslijDobrze(formData) {
  return fetch("/api/upload", {
    method: "POST",
    body: formData, // DOBRZE - fetch sam ustawia Content-Type z boundary
  });
}

