document.getElementById("post-form").addEventListener("submit", async (e) => {
  e.preventDefault();
  const przycisk = e.target.querySelector("button[type=submit]");
  przycisk.disabled = true;

  try {
    const tytul = document.getElementById("post-title").value;
    await utworzPost({ tytul, userId: 1 });
  } finally {
    przycisk.disabled = false;
  }
});

// multipart/form-data (format uzywany przez FormData) wymaga unikalnego
// 'boundary' - ciagu znakow oddzielajacego poszczegolne czesci przesylki
// (kazde pole, kazdy plik). Przegladarka generuje ten boundary
// AUTOMATYCZNIE i dolacza go do naglowka Content-Type, TYLKO gdy SAMA
// ustawia ten naglowek. Reczne wpisanie 'Content-Type: multipart/
// form-data' nadpisuje ta automatyke, usuwajac boundary - serwer nie
// bedzie w stanie poprawnie rozdzielic i odczytac poszczegolnych czesci
// przesylki.
